          "code": "import numpy as np\nfrom sklearn.cluster import DBSCAN\n\ndef dbscan_first_principles(X: np.ndarray, eps: float, min_samples: int) -> tuple[np.ndarray, np.ndarray]:\n    \"\"\"\n    Implementasi DBSCAN (Ester et al. 1996) dari prinsip pertama dengan BFS.\n    Mengembalikan:\n      labels : array (N,) dengan -1 = noise, 0..K-1 = ID klaster\n      roles  : array (N,) string 'CORE', 'BORDER', atau 'NOISE'\n    \"\"\"\n    n = X.shape[0]\n    # Matriks jarak Euclidean berpasangan O(N^2)\n    diff = X[:, None, :] - X[None, :, :]\n    D = np.sqrt(np.sum(diff ** 2, axis=2))\n\n    neighbors = [np.flatnonzero(D[i] <= eps) for i in range(n)]\n    is_core = np.array([len(nb) >= min_samples for nb in neighbors], dtype=bool)\n\n    labels = np.full(n, -2, dtype=int)  # -2 = belum dikunjungi, -1 = noise\n    cluster_id = 0\n\n    for i in range(n):\n        if labels[i] != -2:\n            continue\n        if not is_core[i]:\n            labels[i] = -1\n            continue\n        # Ekspansi BFS dari core point i\n        labels[i] = cluster_id\n        queue = list(neighbors[i])\n        head = 0\n        while head < len(queue):\n            q = queue[head]\n            head += 1\n            if labels[q] == -1:\n                labels[q] = cluster_id  # Border point direkrut dari status noise sementara\n            elif labels[q] != -2:\n                continue\n            else:\n                labels[q] = cluster_id\n                if is_core[q]:\n                    for nb in neighbors[q]:\n                        if labels[nb] in (-2, -1):\n                            queue.append(int(nb))\n        cluster_id += 1\n\n    roles = np.where(is_core, \"CORE\", np.where(labels >= 0, \"BORDER\", \"NOISE\"))\n    return labels, roles\n\n# 1) Verifikasi terhadap Scikit-Learn pada 2 Klaster + Titik Border + 4 Outlier\nrng = np.random.default_rng(224)\nX_demo = np.vstack([\n    rng.normal([0.0, 0.0], 0.35, size=(40, 2)),\n    rng.normal([2.6, 0.0], 0.35, size=(40, 2)),\n    np.array([[-2.2, 2.0], [1.3, 2.3], [4.5, -1.8], [1.3, -2.1]]),\n])\n\nlbl_our, roles_our = dbscan_first_principles(X_demo, eps=0.55, min_samples=5)\nsk_db = DBSCAN(eps=0.55, min_samples=5).fit(X_demo)\n\ncore_match = np.array_equal(lbl_our[roles_our == \"CORE\"], sk_db.labels_[roles_our == \"CORE\"])\nall_match = np.array_equal(lbl_our, sk_db.labels_)\n\nprint(\"=== 1. Verifikasi DBSCAN First-Principles vs sklearn.cluster.DBSCAN ===\")\nprint(f\"Distribusi Peran Titik | CORE={int(np.sum(roles_our == 'CORE'))}, BORDER={int(np.sum(roles_our == 'BORDER'))}, NOISE={int(np.sum(roles_our == 'NOISE'))}\")\nprint(f\"Klaster Ditemukan      | Scratch={len(set(lbl_our) - {-1})} vs Sklearn={len(set(sk_db.labels_) - {-1})}\")\nprint(f\"Kesamaan Label Core    | {core_match} | Kesamaan Seluruh Label = {all_match}\")\n\n# 2) Bukti Asimetri Border Point: Titik Border di Irisan 2 Core Berbeda Tergantung Urutan Baris!\n# Klaster A di x=0.0 (3 titik core), Klaster B di x=1.6 (3 titik core), 1 titik jembatan di x=0.8 (eps=0.85)\nX_ambig = np.array([\n    [0.0, 0.0], [0.05, 0.0], [-0.05, 0.0],   # Core Klaster A (indeks 0,1,2)\n    [0.80, 0.0],                              # Titik BORDER tepat di tengah (indeks 3, tetangga A & B)\n    [1.6, 0.0], [1.65, 0.0], [1.55, 0.0],    # Core Klaster B (indeks 4,5,6)\n])\n# eps=0.85, min_samples=4 -> titik 0..2 punya 4 tetangga (0,1,2,3 -> CORE!), titik 4..6 punya 4 tetangga (4,5,6,3 -> CORE!),\n# tetapi titik 3 punya 7 tetangga? Agar titik 3 murni BORDER (< min_samples), geser agar hanya 1 titik dari A dan 1 dari B <= eps!\nX_border = np.array([\n    [0.00, 0.0], [0.05, 0.0], [0.10, 0.0], [0.40, 0.0],   # Core A (indeks 0..3; eps=0.50 -> semua >=4 tetangga)\n    [0.85, 0.0],                                           # Titik BORDER (indeks 4): jarak ke idx 3 = 0.45, ke idx 5 = 0.45 -> hanya 3 tetangga (<4)!\n    [1.30, 0.0], [1.60, 0.0], [1.65, 0.0], [1.70, 0.0],   # Core B (indeks 5..8; eps=0.50 -> semua >=4 tetangga)\n])\nlbl_fwd, rol_fwd = dbscan_first_principles(X_border, eps=0.50, min_samples=4)\n# Balik urutan baris input lalu petakan kembali ke indeks asli\nlbl_rev_raw, _ = dbscan_first_principles(X_border[::-1], eps=0.50, min_samples=4)\nlbl_rev = lbl_rev_raw[::-1]\n\na_fwd, b_fwd, mid_fwd = int(lbl_fwd[0]), int(lbl_fwd[8]), int(lbl_fwd[4])\na_rev, b_rev, mid_rev = int(lbl_rev[0]), int(lbl_rev[8]), int(lbl_rev[4])\n\nprint(\"\\n=== 2. Audit Ketergantungan Urutan Baris pada Border Point di Irisan Dua Klaster ===\")\nprint(f\"Peran Titik Tengah (indeks 4) : {rol_fwd[4]} (terjangkau langsung dari Core A maupun Core B!)\")\nprint(f\"Urutan Normal  -> Titik 4 masuk klaster: {'A' if mid_fwd == a_fwd else 'B'} (Label A={a_fwd}, Mid={mid_fwd}, B={b_fwd})\")\nprint(f\"Urutan Terbalik-> Titik 4 masuk klaster: {'A' if mid_rev == a_rev else 'B'} (Label A={a_rev}, Mid={mid_rev}, B={b_rev})\")",
