          "code": "import numpy as np\nfrom sklearn.cluster import DBSCAN, HDBSCAN, OPTICS\nfrom sklearn.datasets import make_moons\nfrom sklearn.metrics import adjusted_rand_score\n\nrng = np.random.default_rng(228)\n\n# Arena Multi-Densitas + Non-Konveks + Outlier Eksternal:\n#   Klaster 0: Bola super rapat (sigma=0.11, pusat [0.0, 0.0])\n#   Klaster 1: Bola rapat berdekatan (sigma=0.11, pusat [0.78, 0.0]) -> jarak antar tepi kecil!\n#   Klaster 2: Bola sangat renggang (sigma=1.15, pusat [6.2, 0.4]) -> 10x lebih renggang!\n#   Klaster 3: Busur lengkung non-konveks (bulan sabit atas)\n#   Outlier  : 24 titik acak jauh dari interior seluruh klaster\nc0 = rng.normal([0.0, 0.0], 0.11, size=(90, 2))\nc1 = rng.normal([0.78, 0.0], 0.11, size=(90, 2))\nc2 = rng.normal([6.2, 0.4], 1.15, size=(90, 2))\nmoons_x, moons_y = make_moons(n_samples=180, noise=0.055, random_state=42)\nc3 = moons_x[moons_y == 0] * 1.4 + np.array([0.8, 3.2])\n\n# Bangkitkan 24 outlier sejati di pinggiran jauh (jarak minimal > 2.2 dari setiap titik klaster inti)\ninliers = np.vstack([c0, c1, c2, c3])\nout_list = []\nwhile len(out_list) < 24:\n    cand = rng.uniform([-3.2, -3.5], [10.5, 6.8], size=(1, 2))\n    if np.min(np.linalg.norm(inliers - cand, axis=1)) > 1.8:\n        out_list.append(cand[0])\noutliers = np.array(out_list)\n\nX = np.vstack([inliers, outliers])\ny_inlier = np.repeat(np.arange(4), 90)  # 360 inlier sejati lintas 4 klaster\n\n# 1) Cari DBSCAN terbaik lewat grid search eps (keunggulan oracle tidak adil untuk DBSCAN!)\nbest_db = (-1.0, 0.0, None)\nfor eps_cand in np.linspace(0.14, 1.40, 30):\n    lbl = DBSCAN(eps=float(eps_cand), min_samples=8).fit_predict(X)\n    ari = float(adjusted_rand_score(y_inlier, lbl[:360]))\n    if ari > best_db[0]:\n        best_db = (ari, float(eps_cand), lbl)\n\n# 2) OPTICS dengan ekstraksi lembah Xi\nopt = OPTICS(min_samples=8, xi=0.05, min_cluster_size=25).fit(X)\n\n# 3) HDBSCAN native Scikit-Learn 1.9 dengan store_centers='medoid'\nhdb = HDBSCAN(\n    min_cluster_size=25,\n    min_samples=8,\n    cluster_selection_method=\"eom\",\n    store_centers=\"medoid\",\n    copy=False,\n).fit(X)\n\ndef report(name: str, labels: np.ndarray):\n    k_found = len(set(labels) - {-1})\n    ari_in = float(adjusted_rand_score(y_inlier, labels[:360]))\n    out_recall = 100.0 * float(np.mean(labels[360:] == -1))\n    in_noise = 100.0 * float(np.mean(labels[:360] == -1))\n    print(f\"{name:34s} | K={k_found:2d} | ARI(In)={ari_in:.4f} | Outlier Rec={out_recall:5.1f}% | Inlier -1={in_noise:4.1f}%\")\n\nprint(\"=== Arena Multi-Densitas + Non-Konveks + Outlier (4 Klaster Sejati + 24 Outlier) ===\")\nreport(f\"Best Grid DBSCAN (eps={best_db[1]:.2f})\", best_db[2])\nreport(\"OPTICS (min_s=8, xi=0.05)\", opt.labels_)\nreport(\"HDBSCAN (min_cl=25, min_s=8, EOM)\", hdb.labels_)\n\n# Audit probabilities_ dan medoids_ bawaan HDBSCAN\nhi_conf = 100.0 * float(np.mean(hdb.probabilities_[:360] >= 0.70))\nprint(f\"\\nHDBSCAN Medoids Tersimpan : shape={hdb.medoids_.shape} | Inlier Berkeyakinan Tinggi (prob>=0.70) = {hi_conf:.1f}%\")",
          "expectedOutput": "=== Arena Multi-Densitas + Non-Konveks + Outlier (4 Klaster Sejati + 24 Outlier) ===\nBest Grid DBSCAN (eps=0.18)        | K= 7 | ARI(In)=0.7394 | Outlier Rec=100.0% | Inlier -1=34.7%\nOPTICS (min_s=8, xi=0.05)          | K= 4 | ARI(In)=0.4156 | Outlier Rec=100.0% | Inlier -1=48.1%\nHDBSCAN (min_cl=25, min_s=8, EOM)  | K= 4 | ARI(In)=0.9891 | Outlier Rec=100.0% | Inlier -1= 0.8%\n\nHDBSCAN Medoids Tersimpan : shape=(4, 2) | Inlier Berkeyakinan Tinggi (prob>=0.70) = 70.8%",
          "actualOutput": "=== Arena Multi-Densitas + Non-Konveks + Outlier (4 Klaster Sejati + 24 Outlier) ===\nBest Grid DBSCAN (eps=0.18)        | K= 7 | ARI(In)=0.7394 | Outlier Rec=100.0% | Inlier -1=34.7%\nOPTICS (min_s=8, xi=0.05)          | K= 4 | ARI(In)=0.4156 | Outlier Rec=100.0% | Inlier -1=48.1%\nHDBSCAN (min_cl=25, min_s=8, EOM)  | K= 4 | ARI(In)=0.9891 | Outlier Rec=100.0% | Inlier -1= 0.8%\n\nHDBSCAN Medoids Tersimpan : shape=(4, 2) | Inlier Berkeyakinan Tinggi (prob>=0.70) = 70.8%",
