          "id": "code-ml-22-4-ch22_4_diag",
          "title": "Production Audit: Over-Compression 2D vs 12D & Online Out-of-Sample approximate_predict + OOD Rejection",
          "language": "python",
          "filename": "22_4_overcompression_and_online_ood_audit.py",
          "code": "import numpy as np\nfrom sklearn.cluster import HDBSCAN\nfrom sklearn.decomposition import PCA\nfrom sklearn.metrics import adjusted_rand_score\nfrom sklearn.neighbors import NearestNeighbors\nfrom sklearn.preprocessing import Normalizer\n\nrng = np.random.default_rng(2212)\n\n# Bangkitkan 6 topik semantik berdimensi 256D untuk audit over-compression & online approximate_predict\nd_emb, k_topics = 256, 6\ntopic_dirs = rng.standard_normal((k_topics, d_emb))\ntopic_dirs /= np.linalg.norm(topic_dirs, axis=1, keepdims=True)\n\nX_tr_list, X_te_in_list = [], []\nfor c in range(k_topics):\n    tr_c = topic_dirs[c] + rng.normal(0.0, 0.08, size=(75, d_emb))\n    te_c = topic_dirs[c] + rng.normal(0.0, 0.08, size=(20, d_emb))\n    X_tr_list.append(tr_c * rng.uniform(2.0, 6.0, size=(75, 1)))\n    X_te_in_list.append(te_c * rng.uniform(2.0, 6.0, size=(20, 1)))\n\nX_tr = np.vstack(X_tr_list)\ny_tr = np.repeat(np.arange(k_topics), 75)\nX_te_in = np.vstack(X_te_in_list)\ny_te_in = np.repeat(np.arange(k_topics), 20)\n\n# Topik baru yang BELUM pernah terlihat saat fit (Out-of-Distribution / insiden baru!)\nnovel_dir = rng.standard_normal((1, d_emb))\nnovel_dir /= np.linalg.norm(novel_dir)\nX_te_ood = (novel_dir + rng.normal(0.0, 0.08, size=(30, d_emb))) * rng.uniform(2.0, 6.0, size=(30, 1))\n\n# 1) Audit Over-Compression: Memaksa 256D -> 2D Sebelum HDBSCAN vs Sweet Spot 12D-16D\nnormer = Normalizer(norm=\"l2\")\nX_tr_u = normer.fit_transform(X_tr)\nX_te_in_u = normer.transform(X_te_in)\nX_te_ood_u = normer.transform(X_te_ood)\n\nprint(\"=== 1. Audit Over-Compression Sebelum HDBSCAN (256D -> d_red pada 6 Topik) ===\")\nprint(\"Dimensi Reduksi PCA | EVR Kumulatif | Klaster Ditemukan | ARI Train | Inlier Noise\")\nprint(\"-\" * 84)\nfor d_red in [2, 4, 8, 12, 24]:\n    pca_tmp = PCA(n_components=d_red, random_state=42).fit(X_tr_u)\n    Z_tmp = pca_tmp.transform(X_tr_u)\n    h_tmp = HDBSCAN(min_cluster_size=25, min_samples=8, copy=False).fit(Z_tmp)\n    k_f = len(set(h_tmp.labels_) - {-1})\n    print(f\"PCA(n_components={d_red:2d}) | {np.sum(pca_tmp.explained_variance_ratio_):13.4f} | {k_f:17d} | {adjusted_rand_score(y_tr, h_tmp.labels_):9.4f} | {100*np.mean(h_tmp.labels_==-1):11.1f}%\")\n\n# 2) Online Out-of-Sample approximate_predict Berbasis Core-Radius HDBSCAN + OOD Rejection (-1)\npca_prod = PCA(n_components=12, random_state=42).fit(X_tr_u)\nZ_tr = pca_prod.transform(X_tr_u)\nhdb_prod = HDBSCAN(min_cluster_size=25, min_samples=8, store_centers=\"medoid\", copy=False).fit(Z_tr)\n\n# Simpan hanya anggota inti (probabilities_ >= 0.5) & radius batas p95 jarak ke tetangga core dalam klaster\ncore_mask = (hdb_prod.labels_ >= 0) & (hdb_prod.probabilities_ >= 0.5)\nZ_core = Z_tr[core_mask]\ny_core = hdb_prod.labels_[core_mask]\n\nnn_core = NearestNeighbors(n_neighbors=8, metric=\"euclidean\").fit(Z_core)\ncore_radii_per_cluster = {}\nfor c_id in np.unique(y_core):\n    pts_c = Z_core[y_core == c_id]\n    d_c, _ = NearestNeighbors(n_neighbors=8).fit(pts_c).kneighbors(pts_c)\n    # Ambang kepadatan klaster = persentil 98 jarak tetangga ke-8 di dalam klaster tersebut\n    core_radii_per_cluster[int(c_id)] = float(np.percentile(d_c[:, -1], 98))\n\ndef approximate_predict_hdbscan(Z_query: np.ndarray) -> tuple[np.ndarray, np.ndarray]:\n    dists, idxs = nn_core.kneighbors(Z_query, n_neighbors=1)\n    nearest_d = dists[:, 0]\n    nearest_c = y_core[idxs[:, 0]]\n    pred_lbl = np.full(len(Z_query), -1, dtype=int)\n    pred_conf = np.zeros(len(Z_query), dtype=float)\n    for i in range(len(Z_query)):\n        c_cand = int(nearest_c[i])\n        r_max = core_radii_per_cluster[c_cand]\n        if nearest_d[i] <= r_max:\n            pred_lbl[i] = c_cand\n            pred_conf[i] = float(np.clip(1.0 - (nearest_d[i] / (r_max + 1e-12)) * 0.5, 0.0, 1.0))\n    return pred_lbl, pred_conf\n\npred_in, conf_in = approximate_predict_hdbscan(pca_prod.transform(X_te_in_u))\npred_ood, conf_ood = approximate_predict_hdbscan(pca_prod.transform(X_te_ood_u))\n\nprint(\"\\n=== 2. Online Out-of-Sample approximate_predict (Core-Radius Routing + OOD Rejection) ===\")\nprint(f\"Batch Uji In-Distribution (120 dok)  | ARI={adjusted_rand_score(y_te_in, pred_in):.4f} | Diterima={100*np.mean(pred_in>=0):5.1f}% | Mean Conf={np.mean(conf_in[pred_in>=0]):.3f}\")\nprint(f\"Batch Uji Topik Baru OOD  ( 30 dok)  | Ditolak ke -1 (OOD Recall) = {100*np.mean(pred_ood==-1):5.1f}%  <-- Insiden baru tertangkap!\")",
          "expectedOutput": "=== 1. Audit Over-Compression Sebelum HDBSCAN (256D -> d_red pada 6 Topik) ===\nDimensi Reduksi PCA | EVR Kumulatif | Klaster Ditemukan | ARI Train | Inlier Noise\n------------------------------------------------------------------------------------\nPCA(n_components= 2) |        0.1612 |                 5 |    0.8166 |         0.4%\nPCA(n_components= 4) |        0.2942 |                 6 |    1.0000 |         0.0%\nPCA(n_components= 8) |        0.3773 |                 6 |    1.0000 |         0.0%\nPCA(n_components=12) |        0.4058 |                 6 |    1.0000 |         0.0%\nPCA(n_components=24) |        0.4831 |                 6 |    1.0000 |         0.0%\n\n=== 2. Online Out-of-Sample approximate_predict (Core-Radius Routing + OOD Rejection) ===\nBatch Uji In-Distribution (120 dok)  | ARI=1.0000 | Diterima=100.0% | Mean Conf=0.753\nBatch Uji Topik Baru OOD  ( 30 dok)  | Ditolak ke -1 (OOD Recall) = 100.0%  <-- Insiden baru tertangkap!",
          "actualOutput": "=== 1. Audit Over-Compression Sebelum HDBSCAN (256D -> d_red pada 6 Topik) ===\nDimensi Reduksi PCA | EVR Kumulatif | Klaster Ditemukan | ARI Train | Inlier Noise\n------------------------------------------------------------------------------------\nPCA(n_components= 2) |        0.1612 |                 5 |    0.8166 |         0.4%\nPCA(n_components= 4) |        0.2942 |                 6 |    1.0000 |         0.0%\nPCA(n_components= 8) |        0.3773 |                 6 |    1.0000 |         0.0%\nPCA(n_components=12) |        0.4058 |                 6 |    1.0000 |         0.0%\nPCA(n_components=24) |        0.4831 |                 6 |    1.0000 |         0.0%\n\n=== 2. Online Out-of-Sample approximate_predict (Core-Radius Routing + OOD Rejection) ===\nBatch Uji In-Distribution (120 dok)  | ARI=1.0000 | Diterima=100.0% | Mean Conf=0.753\nBatch Uji Topik Baru OOD  ( 30 dok)  | Ditolak ke -1 (OOD Recall) = 100.0%  <-- Insiden baru tertangkap!",
          "explanation": "Membuktikan kejatuhan ARI saat menekan 256D langsung ke 2D (over-compression) vs pemulihan penuh di 8D-24D, lalu mengimplementasikan layanan online approximate_predict berbasis core-radius HDBSCAN yang meraih ARI uji 1.0000 sekaligus menolak 100% topik baru OOD ke -1.",
